import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 0.99, D: 40 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function withApp(fn) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { await fn(base) } finally { server.close() }
}

async function totalFor(items) {
  let total
  await withApp(async (base) => {
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
    assert.equal(res.status, 201)
    const order = await res.json()
    total = order.total
    const got = await (await fetch(`${base}/orders/${order.id}`)).json()
    assert.equal(got.total, total)
  })
  return total
}

// Characterization tests: pin CURRENT behavior, including questionable parts.
test('single item, no discount', async () => assert.equal(await totalFor([{ sku: 'A', qty: 1 }]), 10))
test('multiple lines are summed', async () => assert.equal(await totalFor([{ sku: 'A', qty: 2 }, { sku: 'D', qty: 1 }]), 60))
test('exactly 100 gets no discount (threshold is strictly > 100)', async () => assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100))
test('just over 100 gets 10% off', async () => assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99))
test('large order gets 10% off', async () => assert.equal(await totalFor([{ sku: 'D', qty: 10 }]), 360))
test('discount applies to whole order, not just the excess', async () => assert.equal(await totalFor([{ sku: 'A', qty: 20 }]), 180))
test('cents are truncated (floored), not rounded: 25.5*1 -> 25', async () => assert.equal(await totalFor([{ sku: 'B', qty: 1 }]), 25))
test('discounted total is floored: 101.5*0.9=91.35 -> 91', async () => assert.equal(await totalFor([{ sku: 'B', qty: 3 }, { sku: 'A', qty: 2 }, { sku: 'C', qty: 5 }]) , 91 + 0 * 0 || 0))
test('sub-euro fractions are dropped entirely: 0.99*1 -> 0', async () => assert.equal(await totalFor([{ sku: 'C', qty: 1 }]), 0))
test('empty items rejected', async () => {
  await withApp(async (base) => {
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [] }) })
    assert.equal(res.status, 400)
  })
})
EOF
